    public function testEsAlumno() {
        // Ya es alumno 2016 con legajo definitivo.
        $arrange = ['ua' => 'FBCB', 'tipotitulo' => '1', 'anio_acad' => '2016', 'carrera' => '0303', 'pais_documento' => '54', 'tipo_documento' => '0', 'nro_documento' => '40645628'];
        $expected = "-1";
    
        // Seteo parametros de conexion y llamo a la funcion WS
        $wsdl = $_SESSION['WSDLG'] . "/ingreso" . "?wsdl";    
        $client = new nusoap_client($wsdl, 'wsdl');
        $client->setCredentials($_SESSION['wsUserGuarani'], $_SESSION['wsPassGuarani'], "basic");
        $salidaWS = $client->call($this->funcionWS, $arrange);
        
        $resultado = json_decode($salidaWS);
        $this->assertEquals($expected, $resultado->codigoWS);
    }

